-- copias externas históricas con núcleo completo b966879c7c23420ad27c7faa85be458f18f8b79ea90efae52e6aaa1fa088db98.
BEGIN;
SET LOCAL search_path=pg_catalog,pg_temp;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SELECT pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('vec_autorizacion_atestada_v3:migracion:000118',0));
