SELECT pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('autorizacion_atestada_v3:migracion:externa:000121',0));
SELECT pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('autorizacion_atestada_v3:migracion:externa:000122',0));
SELECT pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('vec_autorizacion_atestada_v3:migracion:000133',0));
DO $convergencia$
DECLARE
